const DAY_IN_MILLISECONDS = 1000 * 60 * 60 * 24
const RELATIVE_DATE_FORMATTER = new Intl.RelativeTimeFormat("en-US", { numeric: "auto" })
const FORMATS = {
  time: { hour: "numeric", minute: "2-digit" },
  date: { month: "short", day: "numeric", year: "numeric" },
  "long-date": { weekday: "long", month: "long", day: "numeric", year: "numeric" },
  datetime: { dateStyle: "full", timeStyle: "short" }
}

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / DAY_IN_MILLISECONDS)
}

export function beginningOfDay(date) {
  // Compare local calendar dates on a UTC scale so 23- and 25-hour DST days
  // still count as exactly one day. Never use the server's timezone for display.
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function parseLocalTime(datetime) {
  // JavaScript otherwise interprets date-only ISO strings as midnight UTC,
  // shifting calendar headings to the previous day in timezones west of UTC.
  if (/^\d{4}-\d{2}-\d{2}$/.test(datetime)) {
    return new Date(`${datetime}T00:00:00`)
  } else {
    return new Date(datetime)
  }
}

export function formatLocalTime(date, style = "time-or-date", now = new Date()) {
  if (style === "relative") {
    return RELATIVE_DATE_FORMATTER.format(signedDifferenceInDays(now, date), "day")
  } else if (style === "time-or-date") {
    return formatTimeOrDate(date, now)
  } else {
    return date.toLocaleString("en-US", FORMATS[style] || FORMATS.datetime)
  }
}

function formatTimeOrDate(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return formatLocalTime(date, "time")
  } else if (Math.abs(days) < 7) {
    return RELATIVE_DATE_FORMATTER.format(days, "day")
  } else {
    const options = { month: "short", day: "numeric" }
    if (date.getFullYear() !== now.getFullYear()) options.year = "numeric"
    return date.toLocaleDateString("en-US", options)
  }
}
