import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatLocalTime, parseLocalTime } from "helpers/date_helpers"

export default class extends BridgeComponent {
  static component = "share"

  shareUrl() {
    this.send("shareUrl", {
      title: document.title,
      url: window.location.href,
      description: this.#description
    })
  }

  get #description() {
    const description = this.bridgeElement.bridgeAttribute("share-description")
    const createdAt = this.bridgeElement.bridgeAttribute("share-created-at")
    const updatedAt = this.bridgeElement.bridgeAttribute("share-updated-at")

    if (createdAt && updatedAt) {
      const dateAdded = formatLocalTime(parseLocalTime(createdAt), "date")
      const dateUpdated = formatLocalTime(parseLocalTime(updatedAt), "date")
      return `Added ${dateAdded} ${description} Updated ${dateUpdated}`
    } else {
      return description
    }
  }
}
